        e.preventDefault();

        const selectedOption = document.querySelector('input[name="notification-preference"]:checked');

        if (selectedOption) {
            const preferenceMap = {
                email: 'Email',
                sms: 'SMS',
                push: 'Push Notifications'
            };

            const selectedPreference = preferenceMap[selectedOption.value];

            console.log(`Notification preference saved: ${selectedPreference}`);

            // Optional: Show a success message
            showSuccessMessage(`Your preference for ${selectedPreference} has been saved!`);

            // Reset form after a brief delay
            setTimeout(() => {
                form.reset();
            }, 2000);
        }
    });

    function showSuccessMessage(message) {
        // Create and show success message
        const messageDiv = document.createElement('div');
        messageDiv.className = 'success-message';
        messageDiv.textContent = message;

        document.body.appendChild(messageDiv);

        // Animate in
        setTimeout(() => {
            messageDiv.classList.add('show');
        }, 10);

        // Remove after 3 seconds
        setTimeout(() => {
            messageDiv.classList.remove('show');
            setTimeout(() => {
                messageDiv.remove();
            }, 300);
        }, 3000);
    }
});

